const routes={
 '/':home,'/integrations':integrations,'/integrations/courier-partners':courierPartners,'/integrations/sales-channels':salesChannels,'/rate-calculator':()=>calculatorShell('rate'),'/weight-calculator':()=>calculatorShell('weight'),'/tracking':tracking,'/blogs':blogs,'/login':login
};
